"""The unchosen readings, and the sameness the seed's clauses generate, found by search.

Derived (paper, D1 and D15)
    * C-H1 (chosen): the equivalence generated by rewriting, one more pair
      asserted together, and raising one term is `result_key`'s.  Checked by
      search (`generated_classes`): every state with at most `n` terms and
      `small` assertions in each relation is joined to its rewritings, to
      itself with one more pair asserted together, and to itself raised at a
      term, the joins made among states of at most `large` assertions per
      relation — with two terms `large = 3 · small` is enough, since two
      same states on two terms differ by raising one term at most `2 · small`
      times.
    * C-H2 (raising every term at once): raising every term once adds `xry`
      and `xsy` at every ordered pair of two different terms — pairs asserted
      together — so the results are the twenty-second's (`raise_all`).
    * C-J2 with raising (letters as placeholders): raising adds as many `r`
      assertions as `s` assertions, so it keeps the twenty-second's C-J2 mark
      `(n, Σ M_r − Σ M_s)`, and the results are C-J2's.
    * C-J3 with raising (loops not taken out): raising touches no loop; a
      result is its loops' two multiplicities and its excess between two
      different terms moved by `g(x) − g(y)`; its cost is the terms, the
      loops' multiplicities in both relations, and the fewest `Σ |e|` between
      two different terms (`key_j3`, `cost_j3`), computed by grouping the
      ninth's exploration of states.
"""

from __future__ import annotations

from collections.abc import Callable, Iterable, Iterator
from itertools import permutations

from ninth.explore import explore as explore_ninth
from twentysecond.readings import key_j2

from twentythird.cost import descend, table_weight
from twentythird.state import DState, Table, empty, normal_table, raise_term, rewrite, rewrite_table

__all__ = [
    "box_states",
    "cost_j3",
    "explore_j3",
    "generated_classes",
    "key_j2",
    "key_j3",
    "raise_all",
    "steps_h1",
]


def raise_all(state: DState) -> DState:
    """Every term raised once (reading C-H2's step)."""
    out = state
    for x in range(state.n):
        out = raise_term(out, x)
    return out


def _vectors(cells: int, left: int) -> Iterator[tuple[int, ...]]:
    if cells == 0:
        yield ()
        return
    for v in range(left + 1):
        for rest in _vectors(cells - 1, left - v):
            yield (v, *rest)


def box_states(n: int, total: int) -> list[DState]:
    """Every state on `n` terms with at most `total` assertions in each relation."""
    cells = n * n
    return [DState(n, r, s) for r in _vectors(cells, total) for s in _vectors(cells, total)]


def steps_h1(state: DState) -> Iterator[DState]:
    """The states one step of the seed's three clauses away: a rewriting, one more pair asserted together,
    one term raised."""
    n = state.n
    for p in permutations(range(n)):
        yield rewrite(state, p)
    for i in range(n * n):
        r = list(state.r)
        s = list(state.s)
        r[i] += 1
        s[i] += 1
        yield DState(n, tuple(r), tuple(s))
    for x in range(n):
        yield raise_term(state, x)


def generated_classes(
    n: int, small: int, large: int, steps: Callable[[DState], Iterable[DState]]
) -> dict[DState, DState]:
    """For every state with at most `small` assertions per relation, the root of its class under the joins
    `steps` makes among the states with at most `large` per relation."""
    states = box_states(n, large)
    parent = {s: s for s in states}

    def find(s: DState) -> DState:
        while parent[s] != s:
            parent[s] = parent[parent[s]]
            s = parent[s]
        return s

    for s in states:
        for t in steps(s):
            if t in parent:
                a, b = find(s), find(t)
                if a != b:
                    parent[a] = b
    return {s: find(s) for s in states if s.total_r <= small and s.total_s <= small}


def key_j3(state: DState) -> tuple[int, tuple[tuple[int, int], ...], Table]:
    """The result of a state under C-J3 with raising: loops' two multiplicities, and the excess between two
    different terms (loops set to zero) in normal form; least over the rewritings."""
    n = state.n
    best: tuple[tuple[tuple[int, int], ...], Table] | None = None
    for p in permutations(range(n)):
        loops = [(0, 0)] * n
        for x in range(n):
            loops[p[x]] = (state.r[x * n + x], state.s[x * n + x])
        table = tuple(
            0 if x == y else state.r[x * n + y] - state.s[x * n + y] for x in range(n) for y in range(n)
        )
        cand = (tuple(loops), normal_table(n, rewrite_table(n, table, p)))
        if best is None or cand < best:
            best = cand
    assert best is not None
    return (n, best[0], best[1])


def cost_j3(state: DState) -> int:
    """C-J3 with raising: terms, both loop multiplicities, and the fewest `Σ |e|` between different terms."""
    n = state.n
    loops = sum(state.r[x * n + x] + state.s[x * n + x] for x in range(n))
    table = tuple(0 if x == y else state.r[x * n + y] - state.s[x * n + y] for x in range(n) for y in range(n))
    return n + loops + table_weight(descend(n, table))


def explore_j3(bound: int, rounds: int) -> dict[tuple[int, tuple[tuple[int, int], ...], Table], tuple[int, DState]]:
    """C-J3 with raising: the ninth's exploration of states, grouped; each result's round and first state."""
    ninth = explore_ninth(empty(), bound, rounds)
    out: dict[tuple[int, tuple[tuple[int, int], ...], Table], tuple[int, DState]] = {}
    for state in sorted(ninth.depth, key=lambda s: (ninth.depth[s], s.n, s.r, s.s)):
        k = key_j3(state)
        if k not in out:
            out[k] = (ninth.depth[state], state)
    return out
